    if value < 0 or width <= 0 or max_steps < 0:
        raise ValueError("invalid bounds")
    low = 0.0
    high = max(1.0, value)
    for _ in range(max_steps):
        if high - low <= width:
            return (low + high) / 2
        middle = (low + high) / 2
        if middle * middle < value:
            low = middle
        else:
            high = middle
    if high - low <= width:
        return (low + high) / 2
    return None

